  board: number[][]
  active_piece: ActivePiece | null
  score: number
  total_lines: number
  level: number
  gravity_interval_ms: number
  next_piece: string
  hold_piece: string | null
  can_hold: boolean
}

const SHAPE_INDICES: Record<string, number> = {
  I: 1, J: 2, L: 3, O: 4, S: 5, T: 6, Z: 7
}

