    vi.mocked((globalThis as any).fetch).mockRejectedValueOnce(new Error('Network disconnected'))

    render(<App />)

    fireEvent.click(screen.getByText('Start New Game'))

    await waitFor(() => {
      expect(screen.getByText('Network disconnected')).toBeTruthy()
    })
